function portableReferences(document,targetId,assets,resolve){
 const target=document.nodes.find(n=>n.id===targetId);
 if(!target||!target.params.model||target.params.model==='MiniMax H3')return document;
 const p=target.params;
 const ids=[...new Set([...(p.h3_refs||[]),...(p.h3?.mode==='frames'?[p.h3.first_frame,p.h3.last_frame]:[])].filter(Boolean))];
 const images=ids.filter(id=>assets.some(a=>a.id===id&&a.kind==='ref'));
 if(!images.length)return document;
 const nodes=[...document.nodes],edges=[...document.edges];
 for(const id of images){
  let source=nodes.find(n=>n.id!==targetId&&n.type==='image'&&resolve(n)===id);
  if(!source){source={...target,id:crypto.randomUUID(),type:'image',title:'参考图片',prompt:'',media_id:id,active_job:null,asset_packs:[],params:{...p,model:'muse-image',h3:null,h3_refs:[]},x:target.x-300,y:target.y+images.indexOf(id)*80};nodes.push(source);}
  if(!edges.some(e=>e.target===targetId&&e.source===source.id))edges.push({id:crypto.randomUUID(),source:source.id,target:targetId});
 }
 return {...document,edges,nodes:nodes.map(n=>n.id===targetId?{...n,params:{...p,h3_refs:(p.h3_refs||[]).filter(id=>!images.includes(id)),h3:p.h3?{...p.h3,first_frame:images.includes(p.h3.first_frame)?null:p.h3.first_frame,last_frame:images.includes(p.h3.last_frame)?null:p.h3.last_frame}:null}}:n)};
}

